import { verifyAccount, type StoredAccount } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

async function expectFailure(accounts: readonly StoredAccount[], email: string, secret: string, message: string): Promise<void> {
  try {
    await verifyAccount(accounts, email, secret);
  } catch (error) {
    assert(error instanceof Error && error.message === 'Verification failed', message);
    return;
  }
  throw new Error(`${message}: did not reject`);
}

async function run(): Promise<void> {
  const accounts: StoredAccount[] = [
    { id: '1', name: 'First', email: 'User@example.com', image: 'one.png', secret: 'Secret' },
    { id: '2', name: 'Duplicate', email: 'User@example.com', image: 'two.png', secret: 'Secret' },
    { id: '3', name: 'Lowercase', email: 'user@example.com', image: 'three.png', secret: 'Secret' }
  ];
  const before = JSON.stringify(accounts);
  const profile = await verifyAccount(accounts, 'User@example.com', 'Secret');
  assert(JSON.stringify(profile) === JSON.stringify({ id: '1', name: 'First', email: 'User@example.com', image: 'one.png' }), 'returns first exact match in input order');
  assert(profile !== (accounts[0] as unknown), 'profile does not alias stored account');
  assert(!Object.prototype.hasOwnProperty.call(profile, 'secret'), 'profile does not expose secret');
  assert(JSON.stringify(accounts) === before, 'does not mutate accounts');

  profile.name = 'Changed';
  assert(accounts[0].name === 'First', 'profile mutation does not affect account');
  const next = await verifyAccount(accounts, 'User@example.com', 'Secret');
  assert(next !== profile && next.name === 'First', 'each successful call allocates a fresh profile');

  const lowercase = await verifyAccount(accounts, 'user@example.com', 'Secret');
  assert(lowercase.id === '3', 'email matching is case-sensitive');
  await expectFailure(accounts, 'USER@example.com', 'Secret', 'rejects email case mismatch');
  await expectFailure(accounts, 'User@example.com', 'secret', 'rejects secret case mismatch');
  await expectFailure(accounts, '', '', 'rejects empty credentials');
  await expectFailure([], 'User@example.com', 'Secret', 'rejects missing account');
  assert(JSON.stringify(accounts) === before, 'failed verification does not mutate accounts');
}

void run().catch((error: unknown) => {
  throw error;
});

